// Regenerates the pure logic of the web's 3D brain from the desktop app, so the two cannot drift.
//
//   1. SYNC — copies the app's pure brain modules (src/components/Brain/*.ts: mesh, vertex
//      assignment, derived data, segment buffers, look, shaders) into docs/src/brain/, rewriting
//      only their relative imports and adding a "do not edit" header (brain-sync.mjs, which the
//      app's test tests/components/brainWebSync.test.ts also uses). Those copies are what
//      `astro check` type-checks against the web's own graph types (graph.ts).
//   2. BUNDLE — esbuild turns docs/src/brain/nf-mesh.entry.ts and nf-graph.entry.ts into the
//      served IIFEs public/brain/nf-mesh.js (window.NF.mesh) and public/brain/nf-graph.js
//      (window.NF.graph + window.NF.look). Unminified, ES2020 (nothing is lowered: the mesh is
//      floating-point code whose exact operations are part of a tested contract).
//
// public/brain/nf-brain.js (the three.js scene) is NOT generated: it is a hand port of the app's
// BrainScene.tsx against three r128 and reads everything else from NF.mesh / NF.graph / NF.look.
//
//   npm run brain         regenerate (then bump the ?v= cache-buster in public/brain/nf-load.js)
//   npm run brain:check   exit 1 if any copy or bundle is out of date with the app

import { build } from 'esbuild'
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import { COPIES, lf, toWebCopy } from './brain-sync.mjs'

const DOCS = join(dirname(fileURLToPath(import.meta.url)), '..')
const APP_BRAIN = join(DOCS, '..', 'src', 'components', 'Brain')
const WEB_BRAIN = join(DOCS, 'src', 'brain')
const PUBLIC_BRAIN = join(DOCS, 'public', 'brain')
const check = process.argv.includes('--check')

const stale = []

async function emit(path, content) {
  let current = null
  try { current = lf(await readFile(path, 'utf8')) } catch { /* missing */ }
  if (current === content) return
  if (check) { stale.push(relative(DOCS, path)); return }
  await writeFile(path, content)
  console.log('wrote', relative(DOCS, path))
}

// ── 1. sync the copies ──
for (const [from, to] of Object.entries(COPIES)) {
  await emit(join(WEB_BRAIN, to), toWebCopy(from, await readFile(join(APP_BRAIN, from), 'utf8')))
}

// ── 2. bundle the served scripts ──
const BANNER =
  '/* GENERATED by docs/scripts/build-brain.mjs from docs/src/brain (synced from the app\'s\n' +
  '   src/components/Brain). Do not edit by hand: run `npm run brain` in docs/, then bump the\n' +
  '   ?v= of the three entries in nf-load.js. */'
for (const name of ['nf-mesh', 'nf-graph']) {
  const out = await build({
    entryPoints: [join(WEB_BRAIN, `${name}.entry.ts`)],
    bundle: true,
    format: 'iife',
    target: 'es2020',
    platform: 'browser',
    minify: false,
    write: false,
    charset: 'utf8',
    legalComments: 'none',
    banner: { js: BANNER },
    logLevel: 'warning',
  })
  await emit(join(PUBLIC_BRAIN, `${name}.js`), lf(out.outputFiles[0].text))
}

if (check) {
  if (stale.length) {
    console.error('Out of date with the app (run `npm run brain` in docs/):\n  ' + stale.join('\n  '))
    process.exit(1)
  }
  console.log('brain: copies and bundles are up to date')
}
